import java.io.*;
import java.util.*;

public class Task7 {
    public static void main(String[] args) {
        Fastscanner in = new FastScanner(System.in);
        int n = in.nextInt();
        int B = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        List<Integer> costs = new LinkedList<>();
        int cntEven = 0, cntOdd = 0;
        for (int i = 0; i < n; i++) {
            if ((a[i] & 1) == 0) cntEven++;
            else cntOdd++;
            if (cntEven == cntOdd && i != n - 1) {
                int cost = a[i] - a[i+1];
                if (cost < 0) cost = -cost;
                costs.add(cost);
            }
        }
        Collections.sort(costs);
        int ans = 0;
        Iterator<Integer> it = costs.iterator();
        while (it.hasNext() && B >= 0) {
            int x = it.next();
            if (B < x) break;
            B -= x;
            ans++;
        }
        System.out.println(ans);
    }

    static class Fastscanner {
        BufferedReader br;
        StringTokenizer st;
        Fastscanner(InputStream f) { br = new BufferedReader(new InputStreamReader(f)); }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {}
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }
}
